-- =============================================================================
-- Payroll MIS — MOCK TEST DATA (seed). Generated by scripts/mis-mock/generate_seed.mjs — do not hand-edit.
--
-- Local / staging ONLY. Inserts mock employees (MOCK-E0001…), salary months Oct 2025 – Oct 2026,
-- MIS masters and statutory payment rows so all 7 Payroll MIS reports reproduce the sample figures.
-- Insert-only: no existing row is updated or deleted. Every inserted row is listed in
-- public.mis_mock_registry; scripts/mis-mock/cleanup_mis_mock.sql removes all of it.
--
-- Run (psql):      psql "$STAGING_DB_URL" -v ON_ERROR_STOP=1 -f scripts/mis-mock/seed_mis_mock.sql
-- Run (SQL editor): paste the whole file and run it once.
--
-- SAFETY: the seed refuses to run until you confirm the target is NOT production by
-- un-commenting the next line. It also refuses if real salary months exist for Oct 2025 – Oct 2026.
-- =============================================================================
-- SELECT set_config('mis_mock.confirm', 'not-production', false);

SELECT current_database() AS target_database, inet_server_addr() AS target_host, inet_server_port() AS target_port,
       current_user AS connected_as, current_setting('mis_mock.confirm', true) AS confirmation;

BEGIN;

DO $guard$
DECLARE
  v_real integer;
BEGIN
  RAISE NOTICE 'Payroll MIS mock seed — target database: % (host %, port %)',
    current_database(), coalesce(inet_server_addr()::text, 'local socket'), coalesce(inet_server_port()::text, '-');
  IF coalesce(current_setting('mis_mock.confirm', true), '') <> 'not-production' THEN
    RAISE EXCEPTION 'Refusing to seed: confirm the target is local/staging by running SELECT set_config(''mis_mock.confirm'', ''not-production'', false); first.';
  END IF;
  IF current_database() ~* 'prod' THEN
    RAISE EXCEPTION 'Refusing to seed: database name "%" looks like production.', current_database();
  END IF;
  IF to_regclass('public.admin_payroll_mis_snapshot') IS NULL OR to_regclass('public.admin_payroll_statutory_payments') IS NULL
     OR to_regclass('public.admin_payroll_employee_tags') IS NULL THEN
    RAISE EXCEPTION 'Refusing to seed: the Payroll MIS migrations are not applied on this database.';
  END IF;
  IF to_regclass('public.mis_mock_registry') IS NOT NULL THEN
    RETURN; -- already seeded; the main block below skips
  END IF;
  SELECT count(*) INTO v_real FROM public.admin_salary_month_runs WHERE month_key BETWEEN '2025-10' AND '2026-10';
  IF v_real > 0 THEN
    RAISE EXCEPTION 'Refusing to seed: % real salary month(s) already exist between 2025-10 and 2026-10 (one run per month is allowed).', v_real;
  END IF;
  SELECT count(*) INTO v_real FROM public.admin_payroll_statutory_payments WHERE wage_month BETWEEN '2025-10' AND '2026-10';
  IF v_real > 0 THEN
    RAISE EXCEPTION 'Refusing to seed: % statutory payment row(s) already exist for 2025-10 – 2026-10.', v_real;
  END IF;
  SELECT count(*) INTO v_real FROM public.admin_ifsp_employee_master WHERE employee_id ILIKE 'MOCK-%' OR employee_code ILIKE 'MOCK-%';
  IF v_real > 0 THEN
    RAISE EXCEPTION 'Refusing to seed: % employee(s) with a MOCK- code exist but the mock registry is missing.', v_real;
  END IF;
  IF to_regclass('public.profiles') IS NOT NULL THEN
    EXECUTE 'SELECT count(*) FROM public.profiles WHERE employee_code ILIKE ''MOCK-%''' INTO v_real;
    IF v_real > 0 THEN
      RAISE EXCEPTION 'Refusing to seed: a login profile uses a MOCK- employee code.';
    END IF;
  END IF;
END
$guard$;

-- ---------------------------------------------------------------------------
-- Fixture (temporary tables, dropped at commit)
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE _mm_emp (
  n integer PRIMARY KEY, code text, name text, bucket text, vertical text, dept text, designation text, location text,
  emp_type text, doj date, dor date, status text, status_reason text, uan text, esic text, grade text, cost_centre text,
  position_type text, exit_reason text, rate numeric, basic numeric, hra numeric, special numeric,
  grat numeric, bonus numeric, med numeric, revision_type text, wef date, ctc_full numeric
) ON COMMIT DROP;

CREATE TEMP TABLE _mm_line (
  month text, n integer, present numeric, total integer, rate numeric, basic_full numeric, basic_earned numeric,
  hra_full numeric, hra_earned numeric, special_full numeric, special_earned numeric, pf_wage numeric, gross numeric,
  emp_pf numeric, emp_esic numeric, pt numeric, tds numeric, loan numeric, total_ded numeric, net numeric,
  er_pf_full numeric, er_esic_full numeric, incentive numeric, ot numeric, arrears numeric, other_earn numeric,
  ee_lwf numeric, er_lwf numeric
) ON COMMIT DROP;

-- Oct 2025 – Mar 2026: same people and amounts as Apr 2026 (full months); LWF in Dec 2025.
SELECT mk.month, l.n, d.days, d.days, l.rate, l.basic_full, l.basic_full, l.hra_full, l.hra_full, l.special_full, l.special_full,
       l.pf_wage, l.gross, l.emp_pf, l.emp_esic, l.pt, l.tds, l.loan,
       l.total_ded + CASE WHEN mk.month IN ('2025-12', '2026-06') THEN 6.00 ELSE 0 END,
       l.net - CASE WHEN mk.month IN ('2025-12', '2026-06') THEN 6.00 ELSE 0 END,
       l.er_pf_full, l.er_esic_full, l.incentive, l.ot, l.arrears, l.other_earn,
       CASE WHEN mk.month IN ('2025-12', '2026-06') THEN 6.00 ELSE 0 END,
       CASE WHEN mk.month IN ('2025-12', '2026-06') THEN 12.00 ELSE 0 END
FROM _mm_line l
CROSS JOIN (VALUES ('2025-10'), ('2025-11'), ('2025-12'), ('2026-01'), ('2026-02'), ('2026-03')) AS mk(month)
CROSS JOIN LATERAL (SELECT extract(day FROM (to_date(mk.month || '-01', 'YYYY-MM-DD') + interval '1 month - 1 day'))::int AS days) d
WHERE l.month = '2026-04';

-- Oct 2026 Draft: copy of Sep 2026 (never locked, must never appear in reports).
SELECT '2026-10', n, CASE WHEN present = 0 THEN 0 ELSE 31 END, 31, rate, basic_full, basic_full, hra_full, hra_full,
       special_full, special_full, pf_wage, gross, emp_pf, emp_esic, pt, tds, loan, total_ded, net,
       er_pf_full, er_esic_full, 0, 0, 0, 0, 0, 0
FROM _mm_line WHERE month = '2026-09' AND present > 0;

CREATE TEMP TABLE _mm_struct (month text, n integer, grat numeric, bonus numeric, med numeric) ON COMMIT DROP;

CREATE TEMP TABLE _mm_budget (month text, vertical text, headcount numeric, ctc numeric) ON COMMIT DROP;

-- ---------------------------------------------------------------------------
-- Seed
-- ---------------------------------------------------------------------------
DO $seed$
DECLARE
  v_month text;
  v_run uuid;
  v_ok boolean;
  v_msg text;
  v_n integer;
  v_access_email text := coalesce(nullif(current_setting('mis_mock.vertical_head_email', true), ''), 'mis.vertical.head@example.test');
  v_user uuid;
  v_dept text;
  v_action text;
  v_via_rpc integer := 0;
  v_via_guard integer := 0;
BEGIN
  IF to_regclass('public.mis_mock_registry') IS NOT NULL THEN
    RAISE NOTICE 'Mock data is already seeded (public.mis_mock_registry exists). Nothing to do — run cleanup_mis_mock.sql first to re-seed.';
    RETURN;
  END IF;

  CREATE TABLE public.mis_mock_registry (
    table_name text NOT NULL,
    row_key text NOT NULL,
    source text NOT NULL DEFAULT 'mock_mis',
    inserted_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (table_name, row_key)
  );
  COMMENT ON TABLE public.mis_mock_registry IS
    'Payroll MIS mock data: every row inserted by scripts/mis-mock/seed_mis_mock.sql. Dropped by cleanup_mis_mock.sql.';
  ALTER TABLE public.mis_mock_registry ENABLE ROW LEVEL SECURITY;
  REVOKE ALL ON public.mis_mock_registry FROM PUBLIC, anon, authenticated;

  -- Employees (employee_code left empty so leave / hierarchy / login sync triggers do nothing).
     status, status_reason, uan_no, esic_no, created_by)
  SELECT code, name, designation, dept, location, emp_type, doj, dor, status, status_reason, uan, esic, 'mock_mis'
  FROM _mm_emp ORDER BY n;

  CREATE TEMP TABLE _mm_map ON COMMIT DROP AS
  SELECT e.n, m.id AS master_id FROM _mm_emp e JOIN public.admin_ifsp_employee_master m ON m.employee_id = e.code;
  SELECT count(*) INTO v_n FROM _mm_map;
  IF v_n <> (SELECT count(*) FROM _mm_emp) THEN
    RAISE EXCEPTION 'Mock employee mapping failed (% of % rows).', v_n, (SELECT count(*) FROM _mm_emp);
  END IF;
  SELECT 'admin_ifsp_employee_master', master_id::text FROM _mm_map;

  -- Employee tags (vertical, grade, cost centre, position type, exit reason, state = Gujarat).
  SELECT p.master_id, e.vertical, e.grade, e.cost_centre, e.position_type, e.exit_reason, 'Gujarat'
  FROM _mm_emp e JOIN _mm_map p USING (n);
  SELECT 'admin_payroll_employee_tags', master_id::text FROM _mm_map;

  -- Department → vertical (only names that do not exist yet; existing rows are never changed).
  FOR v_dept, v_msg IN
    SELECT * FROM (VALUES
      ('Operations / Field', 'manpower'), ('Sales & Business Dev.', 'manpower'), ('Service & Maintenance', 'manpower'),
      ('Admin & Accounts', 'manpower'), ('Service', 'amc'), ('AMC Coordination', 'amc'),
      ('Project Execution', 'projects'), ('Design & Estimation', 'projects'),
      ('Corporate Finance', 'corporate'), ('HR & Admin', 'corporate')) AS d(name, vertical)
  LOOP
    ON CONFLICT (department) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n > 0 THEN
    END IF;
  END LOOP;

  -- Salary structures (CTC). Values are the Apr 2026 state; balancing employees are updated month by month below.
     date_of_joining, gross_monthly, basic_monthly, hra_monthly, special_allowance_monthly, emp_pf_monthly, pt_monthly,
     emp_esic_monthly, esic_eligible, er_pf_monthly, er_esic_monthly, gratuity_monthly, leave_encash_monthly,
     mediclaim_enabled, mediclaim_monthly, bonus_monthly, special_perf_bonus_monthly, ex_gratia_monthly,
     total_b_monthly, ctc_monthly, ctc_annual, take_home_monthly)
  SELECT p.master_id, true, 'annexure_2026', 'old', CASE WHEN e.emp_type = 'probation' THEN 'probation' ELSE 'confirmed' END,
         e.revision_type, 'MOCK data (mock_mis)', e.wef, e.doj, e.rate, e.basic, e.hra, e.special,
         CASE WHEN e.uan IS NOT NULL THEN round(e.basic * 0.12) ELSE 0 END,
         CASE WHEN e.rate > 12000 THEN 200 ELSE 0 END,
         CASE WHEN e.esic IS NOT NULL THEN ceil(e.rate * 0.0075) ELSE 0 END,
         e.esic IS NOT NULL,
         CASE WHEN e.uan IS NOT NULL THEN round(e.basic * 0.12) ELSE 0 END,
         CASE WHEN e.esic IS NOT NULL THEN ceil(e.rate * 0.0325) ELSE 0 END,
         e.grat, 0, e.med > 0, e.med, 0, 0, e.bonus,
         e.grat + e.bonus + e.med, coalesce(e.ctc_full, e.rate + e.grat + e.bonus + e.med),
         coalesce(e.ctc_full, e.rate + e.grat + e.bonus + e.med) * 12, e.rate
  FROM _mm_emp e JOIN _mm_map p USING (n);
  SELECT 'admin_salary_structures', s.id::text FROM public.admin_salary_structures s JOIN _mm_map p ON p.master_id = s.employee_master_id;

  -- Shared employee: 50 % Vertical A / 50 % Vertical B (split view is off by default).
  SELECT master_id, v.code, 50 FROM _mm_map, (VALUES ('manpower'), ('amc')) AS v(code) WHERE n = 90;
  SELECT 'admin_payroll_cost_allocations', c.id::text FROM public.admin_payroll_cost_allocations c
  JOIN _mm_map p ON p.master_id = c.employee_master_id;

  -- Group mediclaim policy: annual 4,20,000 charged Sep 2026 – Mar 2027 (60,000 a month). Apr–Aug use CTC mediclaim.
  WITH ins AS (
    VALUES ('MOCK Group Mediclaim FY 2026-27', DATE '2026-04-01', DATE '2027-03-31', 420000, 'remaining', DATE '2026-09-01',
            'mock_mis — premium spread over the remaining months from Sep 2026')
    RETURNING id)

  -- Statutory rates (Gujarat). PF rows already exist (seeded by the MIS migration).
  WITH ins AS (
       DATE '2023-04-01', 'mock_mis — Gujarat PT: nil up to 12,000, 200 above (verify notification date)'),
      ('LWF', 'employee', 'Gujarat', NULL, 6, NULL, NULL, DATE '2023-01-01', 'mock_mis — Gujarat LWF employee 6 per half-year (Jun / Dec)'),
      ('LWF', 'employer', 'Gujarat', NULL, 12, NULL, NULL, DATE '2023-01-01', 'mock_mis — Gujarat LWF employer 12 per half-year (Jun / Dec)')
    ON CONFLICT (statute, component, state, effective_from) DO NOTHING
    RETURNING id)

  -- Compliance calendar for Gujarat (TDS / PF / ESI rows for ALL states already exist).
  WITH ins AS (
    ON CONFLICT (statute, state) DO NOTHING
    RETURNING id)

  -- Budget master Apr–Sep 2026 (every hire is within budget).
  WITH ins AS (
    SELECT vertical, month, headcount, ctc FROM _mm_budget
    ON CONFLICT (vertical_code, month_key) DO NOTHING
    RETURNING id)

  -- Alert recipients (test addresses only; nothing is sent unless the server alert job is configured).
  WITH ins AS (
    VALUES ('cfo@example.test', 'MOCK CFO (test address)', true),
           ('compliance@example.test', 'MOCK Compliance (test address)', true)
    ON CONFLICT (email) DO NOTHING
    RETURNING id)

  -- Vertical-scoped report access for a placeholder test login (skipped if that login does not exist).
  SELECT id INTO v_user FROM auth.users WHERE lower(email) = lower(v_access_email) LIMIT 1;
  IF v_user IS NULL THEN
    RAISE NOTICE 'Vertical-head access skipped: create a test login % and re-run cleanup + seed to attach it.', v_access_email;
  ELSE
    WITH ins AS (
      VALUES (v_user, 'manpower', NULL, 'mock_mis — placeholder vertical head (Vertical A)')
      ON CONFLICT DO NOTHING
      RETURNING id)
  END IF;

  -- Default state: only filled if the setting row is missing (an existing row is never changed).
  WITH ins AS (
    ON CONFLICT (key) DO NOTHING
    RETURNING key)

  -- Salary months: processed runs Oct 2025 – Sep 2026 and a Draft Oct 2026, with their lines.
  FOR v_month IN SELECT DISTINCT month FROM _mm_line ORDER BY month LOOP
    VALUES (split_part(v_month, '-', 1)::int, split_part(v_month, '-', 2)::int, v_month,
            extract(day FROM (to_date(v_month || '-01', 'YYYY-MM-DD') + interval '1 month - 1 day'))::int,
            CASE WHEN v_month = '2026-10' THEN 'draft' ELSE 'processed' END, 1,
            jsonb_build_object('mock_mis', true, 'note', 'Payroll MIS mock data'))
    RETURNING id INTO v_run;

       present_days, total_days, pf_basic, pf_earned_basic, basic_full, basic_earned, hra_full, hra_earned, special_full,
       special_allowance, gross_wages, emp_pf, emp_esic, pt_amount, loan, sal_adv, unpaid_paid, tds, total_ded,
       net_salary, bank_amount, computed_json)
    SELECT v_run, p.master_id, e.code, e.name, e.designation, e.doj, true, l.rate,
           l.present, l.total, l.pf_wage, l.pf_wage, l.basic_full, l.basic_earned, l.hra_full, l.hra_earned, l.special_full,
           l.special_earned, l.gross, l.emp_pf, l.emp_esic, l.pt, l.loan, 0, 0, l.tds, l.total_ded, l.net, l.net,
           jsonb_build_object(
             'mock_mis', true,
             'annexure', jsonb_build_object('er_pf_full', l.er_pf_full, 'er_esic_full', l.er_esic_full),
             'perf_incentive_earned', l.incentive,
             'mock_ot', l.ot, 'mock_arrears', l.arrears, 'mock_other_earnings', l.other_earn,
             'mock_ee_lwf', l.ee_lwf, 'mock_er_lwf', l.er_lwf)
    FROM _mm_line l JOIN _mm_emp e USING (n) JOIN _mm_map p USING (n)
    WHERE l.month = v_month;

    UPDATE public.admin_salary_month_runs r
    SET employee_count = t.cnt, total_gross = t.gross, total_deductions = t.ded, total_net = t.net
    FROM (SELECT count(*) AS cnt, sum(gross_wages) AS gross, sum(total_ded) AS ded, sum(net_salary) AS net
          FROM public.admin_salary_month_lines WHERE run_id = v_run) t
    WHERE r.id = v_run;
  END LOOP;

  -- Lock months in order through the lock guard; the after-lock trigger builds the MIS snapshot.
  FOR v_month IN SELECT unnest(ARRAY['2025-10', '2025-11', '2025-12', '2026-01', '2026-02', '2026-03', '2026-04', '2026-05', '2026-06', '2026-07', '2026-08', '2026-09']) LOOP
    UPDATE public.admin_salary_structures s
    SET gratuity_monthly = c.grat, ex_gratia_monthly = c.bonus, mediclaim_monthly = c.med,
        total_b_monthly = c.grat + c.bonus + c.med,
        ctc_monthly = coalesce(s.gross_monthly, 0) + c.grat + c.bonus + c.med,
        ctc_annual = (coalesce(s.gross_monthly, 0) + c.grat + c.bonus + c.med) * 12
    FROM _mm_struct c JOIN _mm_map p USING (n)
    WHERE c.month = v_month AND s.employee_master_id = p.master_id;

    SELECT id INTO v_run FROM public.admin_salary_month_runs WHERE month_key = v_month;
    FOREACH v_action IN ARRAY CASE WHEN v_month = '2026-07' THEN ARRAY['lock', 'unlock', 'lock'] ELSE ARRAY['lock'] END LOOP
      IF v_action = 'lock' THEN
        BEGIN
          PERFORM public.admin_salary_lock_month_run(v_run);
          v_via_rpc := v_via_rpc + 1;
        EXCEPTION WHEN insufficient_privilege THEN
          -- No signed-in Salary Admin (e.g. SQL editor): same guarded update as admin_salary_lock_month_run.
          PERFORM set_config('admin_salary.lock_action', 'lock', true);
          UPDATE public.admin_salary_month_runs
          SET is_locked = true, locked_at = now(),
              summary_json = jsonb_set(coalesce(summary_json, '{}'::jsonb), '{lock_history}',
                coalesce(summary_json -> 'lock_history', '[]'::jsonb)
                || jsonb_build_array(jsonb_build_object('action', 'lock', 'by_email', 'mock_mis seed', 'at', now())))
          WHERE id = v_run;
          PERFORM set_config('admin_salary.lock_action', '', true);
          v_via_guard := v_via_guard + 1;
        END;

        SELECT ok, message INTO v_ok, v_msg FROM public.admin_payroll_mis_job_log
        WHERE run_id = v_run ORDER BY created_at DESC, id DESC LIMIT 1;
        IF NOT coalesce(v_ok, false) THEN
          RAISE EXCEPTION 'MIS snapshot for % failed after lock: %', v_month, coalesce(v_msg, 'no job log row');
        END IF;

        -- The snapshot builder stores overtime, arrears and LWF as 0 (the salary line has no such columns yet):
        -- copy the mock values from the line so Reports 1–6 show them, then refresh that month's deposit rows.
        UPDATE public.admin_payroll_mis_snapshot s
        SET ot_amount = coalesce((l.computed_json ->> 'mock_ot')::numeric, 0),
            arrears = coalesce((l.computed_json ->> 'mock_arrears')::numeric, 0),
            ee_lwf = coalesce((l.computed_json ->> 'mock_ee_lwf')::numeric, 0),
            er_lwf = coalesce((l.computed_json ->> 'mock_er_lwf')::numeric, 0)
        FROM public.admin_salary_month_lines l
        WHERE s.run_id = v_run AND l.run_id = v_run AND l.employee_master_id = s.employee_master_id
          AND (l.computed_json ->> 'mock_mis') = 'true';
        PERFORM public.admin_payroll_mis_sync_statutory_payments(v_run);
      ELSE
        BEGIN
          PERFORM public.admin_salary_unlock_month_run(v_run, 'MOCK: re-lock test');
        EXCEPTION WHEN insufficient_privilege THEN
          PERFORM set_config('admin_salary.lock_action', 'unlock', true);
          UPDATE public.admin_salary_month_runs
          SET is_locked = false, unlocked_at = now(), unlock_reason = 'MOCK: re-lock test',
              summary_json = jsonb_set(coalesce(summary_json, '{}'::jsonb), '{lock_history}',
                coalesce(summary_json -> 'lock_history', '[]'::jsonb)
                || jsonb_build_array(jsonb_build_object('action', 'unlock', 'by_email', 'mock_mis seed', 'at', now(),
                                                        'reason', 'MOCK: re-lock test')))
          WHERE id = v_run;
          PERFORM set_config('admin_salary.lock_action', '', true);
        END;
      END IF;
    END LOOP;
  END LOOP;
  RAISE NOTICE 'Locks: % through the lock function, % through the guarded update (no signed-in Salary Admin).', v_via_rpc, v_via_guard;

  -- Pay the deposits: everything before Sep on time, except Aug PF (3 days late, interest + penalty); Sep TDS on time.
  UPDATE public.admin_payroll_statutory_payments p
  SET paid_on = p.due_date - 2,
      challan_ref = 'MOCK-' || p.statute || '-' || replace(p.wage_month, '-', ''),
      note = 'mock_mis', updated_at = now()
  WHERE p.run_id IN (SELECT row_key::uuid FROM public.mis_mock_registry WHERE table_name = 'admin_salary_month_runs')
    AND p.wage_month < '2026-09' AND NOT (p.wage_month = '2026-08' AND p.statute = 'PF') AND p.due_date IS NOT NULL;
  UPDATE public.admin_payroll_statutory_payments
  SET paid_on = DATE '2026-09-18', challan_ref = 'MOCK-TRRN-102388', interest = 1500, penalty = 350,
      note = 'mock_mis — paid 3 days late', updated_at = now()
  WHERE wage_month = '2026-08' AND statute = 'PF' AND state = 'Gujarat';
  UPDATE public.admin_payroll_statutory_payments
  SET paid_on = DATE '2026-10-06', challan_ref = 'MOCK-CIN-0510221', note = 'mock_mis', updated_at = now()
  WHERE wage_month = '2026-09' AND statute = 'TDS' AND state = 'Gujarat';
  SELECT 'admin_payroll_statutory_payments', id::text FROM public.admin_payroll_statutory_payments
  WHERE run_id IN (SELECT row_key::uuid FROM public.mis_mock_registry WHERE table_name = 'admin_salary_month_runs')
  ON CONFLICT DO NOTHING;

  -- Rule check: a deposit cannot be marked paid without a challan reference.
  BEGIN
    UPDATE public.admin_payroll_statutory_payments SET paid_on = DATE '2026-10-09', challan_ref = NULL
    WHERE wage_month = '2026-09' AND statute = 'PF' AND state = 'Gujarat';
    RAISE EXCEPTION 'mock_mis_check_failed';
  EXCEPTION
    WHEN check_violation THEN
      RAISE NOTICE 'PASS: a payment cannot be marked paid without a challan reference.';
    WHEN raise_exception THEN
      RAISE EXCEPTION 'FAIL: a payment was marked paid without a challan reference.';
  END;

  UPDATE public.mis_mock_registry SET row_key = 'completed' WHERE table_name = '_seed';
  RAISE NOTICE 'Payroll MIS mock data seeded: % employees, % salary months.', (SELECT count(*) FROM _mm_map),
    (SELECT count(*) FROM public.mis_mock_registry WHERE table_name = 'admin_salary_month_runs');
END
$seed$;

COMMIT;
